1 Scraping the reporting format

DATRAS_URL &lt;- "https://datras.ices.dk/Data_products/ReportingFormat.aspx"

get_hidden_fields &lt;- function(page) {
  hid &lt;- page |&gt; html_elements("input[type='hidden']")
  setNames(html_attr(hid, "value"), html_attr(hid, "name"))
}

post_form &lt;- function(handle, hidden, survey_val, record_val) {
  POST(
    handle = handle,
    path   = "/Data_products/ReportingFormat.aspx",
    encode = "form",
    body   = as.list(c(
      hidden,
      `__EVENTTARGET`   = "",
      `__EVENTARGUMENT` = "",
      `ctl00$ContentPlaceHolder1$ddl_Datatype_new` = survey_val,
      `ctl00$ContentPlaceHolder1$ddl_RecordTypes`  = record_val,
      `ctl00$ContentPlaceHolder1$BtnDisplay`       = "Display"
    ))
  ) |&gt; (\(r) read_html(content(r, "raw")))()
}

extract_field_table &lt;- function(page) {
  tbls &lt;- page |&gt; html_elements("table")
  result &lt;- NULL
  for (tbl in tbls) {
    candidate &lt;- tryCatch(html_table(tbl), error = \(e) NULL)
    if (!is.null(candidate) &&
        nrow(candidate) &gt; 3 &&
        "FieldName" %in% names(candidate) &&
        "Mandatory" %in% names(candidate)) {
      result &lt;- candidate
    }
  }
  result
}

# --- Fetch initial page ---
h  &lt;- handle("https://datras.ices.dk")
r0 &lt;- GET(handle = h, path = "/Data_products/ReportingFormat.aspx")
p0 &lt;- read_html(content(r0, "raw"))
hidden0 &lt;- get_hidden_fields(p0)

survey_opts &lt;- p0 |&gt;
  html_elements("#ContentPlaceHolder1_ddl_Datatype_new option") |&gt;
  (\(x) data.frame(
    survey_val  = html_attr(x, "value"),
    survey_name = html_text(x) |&gt; trimws(),
    stringsAsFactors = FALSE
  ))() |&gt;
  filter(survey_val != "none")

record_opts &lt;- p0 |&gt;
  html_elements("#ContentPlaceHolder1_ddl_RecordTypes option") |&gt;
  (\(x) data.frame(
    record_val  = html_attr(x, "value"),
    record_name = html_text(x) |&gt; trimws(),
    stringsAsFactors = FALSE
  ))()

# --- Scrape all combinations ---
scrape_one &lt;- function(survey_val, survey_name, record_val, record_name) {
  Sys.sleep(0.3)
  page &lt;- tryCatch(
    post_form(h, hidden0, survey_val, record_val),
    error = \(e) NULL
  )
  if (is.null(page)) return(NULL)
  tbl &lt;- extract_field_table(page)
  if (is.null(tbl)) return(NULL)
  tbl |&gt;
    select(Order, FieldName, Width, Format, Mandatory,
           any_of(c("Min", "Max"))) |&gt;
    mutate(
      Survey     = survey_val,
      SurveyName = survey_name,
      RecordType = record_name,
      Mandatory  = Mandatory == "True",
      .before    = 1
    )
}

combos &lt;- crossing(survey_opts, record_opts)
results &lt;- pmap(
  list(combos$survey_val, combos$survey_name,
       combos$record_val, combos$record_name),
  scrape_one
)
rf &lt;- bind_rows(results)

5 Common sole in BITS: a bycatch species with a paper trail
Under StandardSpeciesCode = 3 (roundfish only), common sole (Solea solea) is not required to be recorded. Its absence from HL then means not recorded, not absent from the catch. This creates a direct, quantifiable CPUE bias whenever roundfish-only hauls are mixed with full-protocol hauls in the same index.

# CPUE for common sole from BITS via standardized HL
hl_bits &lt;- dr_HL_standardised(
  hh |&gt; filter(Survey == "BITS", HaulValidity == "V"),
  hl |&gt; filter(Survey == "BITS")
) |&gt; collect()

sole_haul &lt;- hl_bits |&gt;
  filter(type == "haul", species == "common sole") |&gt;
  select(.id, Year, n_hour)

bits_hauls &lt;- hh |&gt;
  filter(Survey == "BITS", HaulValidity == "V",
         StandardSpeciesCode %in% c("1", "3")) |&gt;
  select(.id, Year, StandardSpeciesCode) |&gt;
  collect()


bits_all_hauls &lt;- hh |&gt;
  filter(Survey == "BITS", HaulValidity == "V") |&gt;
  select(.id, Year) |&gt;
  collect()

sole_cpue_naive &lt;- bits_all_hauls |&gt;
  left_join(sole_haul |&gt; select(.id, Year, n_hour), by = c(".id", "Year")) |&gt;
  mutate(n_hour = coalesce(n_hour, 0))

sole_cpue_correct &lt;- bits_hauls |&gt;
  filter(StandardSpeciesCode == "1") |&gt;
  left_join(sole_haul |&gt; select(.id, Year, n_hour), by = c(".id", "Year")) |&gt;
  mutate(n_hour = coalesce(n_hour, 0))

pct_std3 &lt;- bits_all_hauls |&gt;
  left_join(
    hh |&gt; filter(Survey == "BITS", HaulValidity == "V") |&gt;
      select(.id, StandardSpeciesCode) |&gt; collect(),
    by = ".id"
  ) |&gt;
  group_by(Year) |&gt;
  summarise(pct_std3 = mean(as.integer(StandardSpeciesCode == "3")) * 100, .groups = "drop")

ratio_df &lt;- left_join(
  sole_cpue_naive   |&gt; group_by(Year) |&gt; summarise(m_naive   = mean(n_hour), .groups = "drop"),
  sole_cpue_correct |&gt; group_by(Year) |&gt; summarise(m_correct = mean(n_hour), .groups = "drop"),
  by = "Year"
) |&gt;
  mutate(ratio = m_naive / m_correct) |&gt;
  left_join(pct_std3, by = "Year") |&gt;
  filter(!is.na(ratio), !is.na(pct_std3))

ratio_df |&gt;
  ggplot(aes(pct_std3, ratio)) +
  geom_hline(yintercept = 1, linetype = "dashed", colour = "grey50") +
  geom_smooth(method = "lm", se = FALSE, colour = "#d73027", linewidth = 0.8) +
  geom_point(size = 2.5, colour = "#2166ac") +
  geom_text(aes(label = Year), hjust = -0.2, size = 3, colour = "grey30") +
  annotate("text", x = 25, y = 0.97,
           label = sprintf("r = %.2f", cor(ratio_df$pct_std3, ratio_df$ratio)),
           colour = "#d73027", size = 4) +
  scale_y_continuous(labels = scales::percent, limits = c(0.6, 1.05)) +
  labs(x = "% of BITS hauls with roundfish-only protocol (std=3)",
       y = "Naive CPUE / correct CPUE",
       title = "BITS common sole — CPUE deflation tracks protocol contamination",
       subtitle = "In 2002, 32 % of hauls were std=3; naive CPUE was only 69 % of correct") +
  theme_bw()








The deflation is near-mechanical (r = −0.99): each percentage point of roundfish-only hauls costs roughly one percentage point of apparent sole CPUE. In 2002, 32 % of BITS hauls used the roundfish-only protocol; the naive index underestimated sole abundance by 31 %.

2 Status: Superseded
June 2026: This document remains as a reference for the three structural problems in the ICES CPUEL product. However, guidance has been updated.
Recommended approach: Use dr_con("HL_standardised") |&gt; filter(type == "length") directly. This pre-computed table covers all 29 DATRAS surveys, addresses all three problems documented here, and is the foundation for IMBUS D2.3 deliverables.
For updated guidance see the obus catch products vignette.

2.1 The HL_standardised product — Recommended for all CPUE work
The IMBUS D2.3 data product is HL_standardised — a pre-computed standardised HL table covering all 29 DATRAS surveys and all species. It is accessible via dr_con("HL_standardised") and can be filtered directly to length-frequency rows without needing to work through the raw HH and HL tables.
library(obus)

# Ready-to-use — no CPUE arithmetic needed. Use this for all new work.
cod &lt;- dr_con("HL_standardised") |&gt;
  filter(type == "length", latin == "Gadus morhua") |&gt;
  collect()
Key properties:

Full haul key (.id): Survey, Year, Quarter, Country, Platform, Gear, StationName, HaulNumber — unambiguous identification
Valid hauls only (HaulValidity == "V" pre-applied)
Not zero-filled at source: use dr_catch_by_haul() or dr_expand_length() downstream
p_females column retains sex composition without a separate sex grouping dimension
All surveys (29 total vs 8 in CPUEL)

The three problems with CPUEL documented below do not apply to HL_standardised.


Code
library(dplyr)
library(ggplot2)
library(tidyr)
library(purrr)
library(obus)

cpuel_surveys &lt;- dr_con("CPUEL") |&gt; distinct(Survey) |&gt; collect() |&gt; pull(Survey)
hh_surveys    &lt;- dr_con("HH")    |&gt; distinct(Survey) |&gt; collect() |&gt; pull(Survey)

# Pre-compute ambiguous short-key counts for inline use
dup_key_summary &lt;- dr_con("HH") |&gt;
  filter(HaulValidity == "V") |&gt;
  mutate(.id2 = paste(Survey, Year, Quarter, Platform, Gear, HaulNumber, sep = ":")) |&gt;
  distinct(.id, .id2) |&gt;
  count(.id2) |&gt;
  filter(n &gt; 1) |&gt;
  collect()

n_ambiguous_keys  &lt;- nrow(dup_key_summary)
n_ambiguous_hauls &lt;- sum(dup_key_summary$n)

# NS-IBTS Q1 2025 specifically
ns25_dup &lt;- dr_con("HH") |&gt;
  filter(Survey == "NS-IBTS", Year == 2025, Quarter == 1, HaulValidity == "V") |&gt;
  mutate(.id2 = paste(Survey, Year, Quarter, Platform, Gear, HaulNumber, sep = ":")) |&gt;
  distinct(.id, .id2) |&gt;
  collect() |&gt;
  group_by(.id2) |&gt;
  filter(n() &gt; 1) |&gt;
  ungroup()
n_ns25_dup_keys  &lt;- n_distinct(ns25_dup$.id2)
n_ns25_dup_hauls &lt;- nrow(ns25_dup)

8 Appendix 2 — Redundant Sections
Sections moved here from the main document to reduce length. They remain part of D2.2 but are not required reading for reviewers of the field format documentation.

8.1 Scope
In scope:

The three DATRAS exchange record types: HH, HL, and CA.
Field-level metadata: names, types, units, descriptions, and known interpretation pitfalls.
The field structure of HL and the conceptual groups within it.
The DataType field and its arithmetic implications for HL fields.
Species resolution: the WoRMS AphiaID system and historical code types.
Survey coverage: year ranges, valid haul counts, and distinct species per survey.
Known issues with the current DATRAS format (naming, DataType, cross-table ambiguities).
Machine-readable field metadata via dr_lookup_fields and dr_lookup_vocabulary ({obus}).

Out of scope for D2.2 (covered in D2.3):

The proposed IMBUS standardised parquet product and data tiers.
Parquet-based distribution and the {obus} access layer.
The unique haul identifier (.id) construction.
CPUE calculation pathways and intermediate data products.
Area standardisation.
Official CPUEA and survey indices: ICES Datacenter products; accessible via dr_get("CPUEA", ...) and dr_get("IDX", ...).
Deployed data service: Deployment to the ICES open access portal is the subject of D2.4.
Per-survey metadata fact sheets: Addressed separately under user requirement UR-Q1.



8.2 Build script deviations from upstream sources
The data-raw/ scripts in {obus} apply corrections and additions to the raw ICES web service output when building dr_lookup_fields and dr_lookup_vocabulary.
dr_lookup_fields — deviations from the ICES web service
Format normalisation. The web service returns format codes in ICES-internal notation; the script maps these to standard R type names: "char" → "chr", "decimal" / "float" → "dbl". Additionally, Year is corrected from "char" to "int" (the web service value is incorrect), and CA NumberAtLength is forced to "dbl" to avoid type ambiguity with the identically-named HL field.
Age / AgeRings / IndividualAge — naming mismatch. The ICES web service field list returns new = "IndividualAge" and old = "AgeRings" for the CA age field. However, icesDatras::getDATRAS(source = "xml") returns this column as Age, and the IMBUS parquet also stores it as Age. The build script maps to new = "Age", old = "Age" to align with actual data. D2.2 uses Age as the canonical field name; IndividualAge (web service) and AgeRings (upload schema) are legacy references only.
Sex field — sex (lowercase) canonical name (interim deviation). The ICES getDatrasFieldList “new” name differs between tables for the same concept: new = "SpeciesSex", old = "Sex" for HL and new = "IndividualSex", old = "Sex" for CA, both drawing on the same vocabulary. The build script maps both to new = "sex" (lowercase) as a temporary canonical name until the ICES Datacenter / DATRAS team resolve the upstream inconsistency. The semantic distinction — visual bulk-catch assessment in HL vs. dissection-based in CA — is preserved in the field descriptions, not in the name. See IMBUS interim canonical names.
aphia canonical name (interim deviation), and DateofCalculation added. The datacenter-resolved WoRMS identifier is not part of the formal DATRAS upload schema and does not appear in getDatrasFieldList — it is added by the ICES datacenter during processing. Crucially, it surfaces under different names depending on the table: Valid_Aphia in the HL and CA exchange tables, but AphiaID (and ValidAphiaID in places) in the derived products (CPUEL, CPUEA, IDX). The build script adds it manually as new = "aphia", old = "Valid_Aphia" for HL and CA, choosing the single name aphia for the whole project. This is an interim measure; the upstream Valid_Aphia / AphiaID / ValidAphiaID ambiguity needs resolution by the ICES Datacenter / external experts. See IMBUS interim canonical names. DateofCalculation is likewise added manually (old = "DateofCalculation") for HH, HL, and CA.
Hand-curated tables. The ICES web service covers only the upload schema (HH, HL, CA, FA). The following tables are entirely hand-curated:







Table
Reason




LT
Web service LT entries use new-style names that do not match getLTassessment() actual output (Ship, StNo, HaulNo)


FL
Columns returned by icesDatras::getFlexFile(); no web service coverage


CPUEL, CPUEA, IDX
Derived products; no web service coverage



dr_lookup_vocabulary — deviations from the ICES Vocabulary Service
The ICES Vocabulary Service uses type code prefixes (TS_, AC_) that do not appear in DATRAS field names. The build script strips these prefixes (e.g. TS_HaulVal → HaulVal) to allow matching against dr_lookup_fields$old. Month, Quarter, and Year are excluded as their vocabulary entries are not useful for categorical lookups.


8.3 Verification code

8.3.1 HL sampling protocol constancy checks
The code below reproduces the statistics cited in HL grouping key constancy violations. Results are pre-computed and cited in the main text; this code is provided for reproducibility. Column names are the standardised names returned by dr_con() (e.g. aphia, sex). Run interactively — these queries scan the full HL parquet and are too slow to execute during document rendering.
library(obus)
library(dplyr)

hl  &lt;- dr_con("HL")
hh  &lt;- dr_con("HH")
grp &lt;- c(".id", "aphia", "sex", "DevelopmentStage", "SpeciesCategory")

# Total groups (all SpeciesValidity): 2,588,831
hl |&gt; group_by(across(all_of(grp))) |&gt; summarise(.groups = "drop") |&gt; count() |&gt; collect()

# Total valid groups (SpeciesValidity == "1"): 2,100,517
hl |&gt; filter(SpeciesValidity == "1") |&gt;
  group_by(across(all_of(grp))) |&gt; summarise(.groups = "drop") |&gt; count() |&gt; collect()

# SpeciesValidity: groups with &gt; 1 distinct value (2,786 of 2,588,831 = 0.1%)
specval_v &lt;- hl |&gt;
  group_by(across(all_of(grp))) |&gt;
  summarise(n_vals = n_distinct(SpeciesValidity), .groups = "drop") |&gt;
  filter(n_vals &gt; 1)

specval_v |&gt;
  left_join(hl |&gt; distinct(.id, Survey), by = ".id") |&gt;
  count(Survey, sort = TRUE) |&gt; collect()            # BTS 1,289; Can-Mar 1,272

# combo breakdown — reduce in R (DuckDB cannot translate the string paste); narrow to
# the candidate hauls first, then keep only the varying groups via an in-R semi_join
combo_keys &lt;- specval_v |&gt; collect()
hl |&gt;
  filter(.id %in% combo_keys$.id) |&gt;
  distinct(.id, aphia, sex, DevelopmentStage, SpeciesCategory, SpeciesValidity) |&gt;
  collect() |&gt;
  semi_join(combo_keys, by = grp) |&gt;
  group_by(across(all_of(grp))) |&gt;
  summarise(combo = paste(sort(unique(SpeciesValidity)), collapse = ", "),
            .groups = "drop") |&gt;
  count(combo, sort = TRUE)                          # {1, 5}: 1,281; {4, 7}: 580

# SubsamplingFactor: groups with &gt; 1 distinct value (389 of 2,100,517 = 0.02%)
sf_v &lt;- hl |&gt;
  filter(SpeciesValidity == "1") |&gt;
  group_by(across(all_of(grp))) |&gt;
  summarise(n_vals = n_distinct(SubsamplingFactor), .groups = "drop") |&gt;
  filter(n_vals &gt; 1)

sf_v |&gt;
  left_join(hl |&gt; distinct(.id, Survey, Country), by = ".id") |&gt;
  count(Country, Survey, sort = TRUE) |&gt; collect()   # GB-SCT 293; DK 82

sf_v |&gt;
  left_join(hh |&gt; distinct(.id, DataType), by = ".id") |&gt;
  count(DataType) |&gt; collect()                       # P: 293; R: 95; C: 1 (= 389)

# TotalNumber: groups with &gt; 1 distinct value (104 of ~2.1 million valid groups = 0.005%)
tn_v &lt;- hl |&gt;
  filter(SpeciesValidity == "1") |&gt;
  group_by(across(all_of(grp))) |&gt;
  summarise(n_vals = n_distinct(TotalNumber), .groups = "drop") |&gt;
  filter(n_vals &gt; 1)

tn_v |&gt; count() |&gt; collect()                        # 104

tn_v |&gt;
  left_join(hl |&gt; distinct(.id, Survey), by = ".id") |&gt;
  count(Survey, sort = TRUE) |&gt; collect()


8.3.2 DataType R size-stratified hauls
Code used to derive the size-stratified DataType R statistics reported in The DataType field.
library(obus)
library(dplyr)

hl  &lt;- dr_con("HL")
hh  &lt;- dr_con("HH")
grp &lt;- c(".id", "aphia", "sex", "DevelopmentStage", "SpeciesCategory")

sf_violations_R &lt;- hl |&gt;
  filter(SpeciesValidity == "1") |&gt;
  group_by(across(all_of(grp))) |&gt;
  summarise(n_sf = n_distinct(SubsamplingFactor), .groups = "drop") |&gt;
  filter(n_sf &gt; 1) |&gt;
  left_join(hh |&gt; distinct(.id, DataType, Country), by = ".id") |&gt;
  filter(DataType == "R")

sf_violations_R |&gt; count()                          # 95 groups
sf_violations_R |&gt; count(Country, sort = TRUE)      # DK: 82; NL: 6; BE: 6; NO: 1 (no GB-SCT)


8.3.3 Surveys table generation
Code used to generate the surveys table in Surveys covered.
library(obus)
library(dplyr)

hh &lt;- dr_con("HH") |&gt; collect()
hl &lt;- dr_con("HL")

survey_stats &lt;- hh |&gt;
  filter(HaulValidity == "V", Survey != "NS-IBTS_UNIFtest") |&gt;
  group_by(Survey) |&gt;
  summarise(year_min = min(Year), year_max = max(Year), n_hauls = n(), .groups = "drop") |&gt;
  arrange(desc(n_hauls))

species_per_survey &lt;- hl |&gt;
  filter(!is.na(aphia), aphia &gt; 0) |&gt;
  group_by(Survey) |&gt;
  summarise(n_species = n_distinct(aphia), .groups = "drop") |&gt;
  collect()

survey_stats |&gt; left_join(species_per_survey, by = "Survey")
